INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(26301, 'Acts 14:16', 'Acts', 14, 16, '&nbsp;په تېرو شوو زمانو کښې هغۀ ټول نسلونه خپلې خوښې ته پرېښې وو چې په کومه ځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26302, 'Acts 14:17', 'Acts', 14, 17, '&nbsp;هغۀ خپل وجود په تاسو د رحم په وسيله ثابت کړو، يعنې په تاسو د آسمان نه باران ورَوى او په خپل موسم کښې فصلونه درکوى، هغه تاسو په خوراک مړوى او ستاسو زړونه خوشحالوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26303, 'Acts 14:18', 'Acts', 14, 18, '&nbsp;په دې وينا سره رسولانو خلق خپل ځان ته د قربانۍ کولو نه ډېره په ګرانه سره منع کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26304, 'Acts 14:19', 'Acts', 14, 19, '&nbsp;بيا د اَنطاکيه او اِکونيوم نه څۀ يهوديان هغه ځائ ته راغلل او خلق يې ځان سره ملګرى کړل. نو هغوئ بيا پولوس سنګسار کړو او د ښار نه يې بهر راښکلو، د هغوئ خيال دا وو چې ګنې مړ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26305, 'Acts 14:20', 'Acts', 14, 20, '&nbsp;خو چې کله مريدان د هغۀ نه راتاو شول، نو هغه پاڅېدو او ښار ته واپس دننه لاړو او په بله ورځ هغه د برنباس سره دربې ښار ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26306, 'Acts 14:21', 'Acts', 14, 21, '&nbsp;په دربې کښې د زيرى اورولو نه وروستو ډېر خلق د عيسىٰ مريدان شول. بيا هغوئ لستره، اِکونيوم او اَنطاکيه ته واپس لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26307, 'Acts 14:22', 'Acts', 14, 22, '&nbsp;هغوئ د ايماندارانو زړونه مضبوط کړل او ډاډګيرنه يې ورکړه چې په خپل ايمان ټينګ او قائم پاتې شى او هغوئ ته يې ووئيل چې، ”د خُدائ پاک بادشاهۍ ته د داخلېدو دپاره به مونږ ډېر تکليفونه زغمو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26308, 'Acts 14:23', 'Acts', 14, 23, '&nbsp;هغوئ په هر جماعت کښې مشران مقرر کړل، او په روژه نيولو او دُعا کولو سره يې هغوئ هغه مالِک ته وسپارل په چا چې يې ايمان راوړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26309, 'Acts 14:24', 'Acts', 14, 24, '&nbsp;بيا هغوئ د پيسيديه نه تير شول او پمفوليه ته راغلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26310, 'Acts 14:25', 'Acts', 14, 25, '&nbsp;او کله چې هغوئ په پرګه کښې کلام واورولو نو هغوئ لاندې اټاليى ته لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26311, 'Acts 14:26', 'Acts', 14, 26, '&nbsp;د اټاليى نه هغوئ اَنطاکيه ته په سمندرى جهاز کښې لاړل چرته چې هغوئ د هغه کار دپاره د خُدائ پاک فضل ته وسپارلے شول کوم چې دوئ اوس پوره کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26312, 'Acts 14:27', 'Acts', 14, 27, '&nbsp;کله چې هغوئ راورسېدل نو هغوئ جماعت يو ځائ راجمع کړو، او د هغه هر څۀ نه يې هغوئ خبر کړل چې خُدائ پاک د دوئ په وسيله کړى وُو، او چې څنګه هغۀ غېر‌يهوديانو ته د ايمان د راوړلو دروازه کولاو کړې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26313, 'Acts 14:28', 'Acts', 14, 28, '&nbsp;او هغوئ هلته تر ډېره وخته پورې د مريدانو سره پاتې شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26314, 'Acts 15:1', 'Acts', 15, 1, '&nbsp;بيا ځينې کسان د يهوديه نه راغلل او ايماندارانو ته يې تعليم شروع کړو چې، ”کۀ تاسو د موسىٰ د شريعت په مطابق سنت نۀ شئ نو خلاصون نۀ شئ موندلے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26315, 'Acts 15:2', 'Acts', 15, 2, '&nbsp;په دې د پولوس او برنباس د هغوئ سره ډېر سخت بحث وشو او جماعت دا فېصله وکړه چې پولوس او برنباس دې سره د نورو ايماندارانو يروشلم ته لاړ شى چې په دې مسئله د رسولانو او د نورو مشرانو سره خبرې وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26316, 'Acts 15:3', 'Acts', 15, 3, '&nbsp;جماعت هغوئ ولېږل او په فينيکې او سامريه ورواوړېدل او هغوئ د غېر‌يهوديانو د ايمان راوړلو خبرې کولې، نو په دې خبره ټول ايمانداران ډېر خوشحاله شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26317, 'Acts 15:4', 'Acts', 15, 4, '&nbsp;کله چې هغوئ يروشلم ته راغلل نو ټول جماعت، رسولانو او مشرانو ورته تود هرکلے وئيلو او بيا يې هغوئ د هغه هر څۀ نه چې خُدائ پاک د هغوئ په وسيله کړى وُو، خبر کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26318, 'Acts 15:5', 'Acts', 15, 5, '&nbsp;بيا د فريسيانو د فرقې څۀ ايمانداران پاڅېدل او وې وئيل چې، ”دا ضرورى دى چې غېر‌يهوديان سنت شى او ورته دې حکم وشى چې د موسىٰ د شريعت پابندى کوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26319, 'Acts 15:6', 'Acts', 15, 6, '&nbsp;نو رسولانو او مشرانو جرګه جوړه کړه چې په خپلو کښې په دې مسئلې مشوره وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26320, 'Acts 15:7', 'Acts', 15, 7, '&nbsp;د اوږد بحث نه پس پطروس پاڅېدو او هغوئ ته يې مخ راواړولو او وې وئيل چې، ”اے زما وروڼو، تاسو په خپله خبر يئ چې په اولو ورځو کښې خُدائ پاک په تاسو کښې زۀ خوښ کړم چې غېر‌يهوديانو ته د زيرى کلام بيان کړم چې هغوئ ايمان راوړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26321, 'Acts 15:8', 'Acts', 15, 8, '&nbsp;او خُدائ پاک چې د هر څۀ نه خبر دے، هغۀ هغوئ ته د روحُ القُدس د ورکولو په وسيله د دې تصديق وکړو چې خُدائ پاک هغوئ هم قبول کړى دى څنګه چې يې مونږ قبول کړى يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26322, 'Acts 15:9', 'Acts', 15, 9, '&nbsp;هغۀ په هغوئ کښې او په مونږ کښې څۀ فرق ونۀ کړو ځکه چې هغۀ د ايمان راوړلو په وسيله د هغوئ زړونه پاک کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26323, 'Acts 15:10', 'Acts', 15, 10, '&nbsp;نو اوس بيا تاسو خُدائ پاک ولې آزمايئ او د دې مريدانو په اوږو داسې جغ ولې ږدئ چې نۀ خو مونږ او نۀ زمونږ پلارانو نيکونو وړلے شو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26324, 'Acts 15:11', 'Acts', 15, 11, '&nbsp;نه، زمونږ عقيده ده چې مونږ د مالِک عيسىٰ د فضل په وسيله خلاصون موندلے دے او دغه شان دوئ هم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26325, 'Acts 15:12', 'Acts', 15, 12, '&nbsp;په دې ټوله غونډه چپ شوله او برنباس او پولوس ته يې غوږ کېښودو چا چې هغه نښې او معجزې بيان کړې چې د دوئ په وسيله خُدائ پاک په غېر‌يهوديانو کښې ښکاره کړې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26326, 'Acts 15:13', 'Acts', 15, 13, '&nbsp;هغوئ چې خبرې بس کړې نو يعقوب ووئيل چې، ”اے زما وروڼو، ما ته غوږ کېږدئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26327, 'Acts 15:14', 'Acts', 15, 14, '&nbsp;شمعون مونږ ته ووئيل چې خُدائ پاک څنګه په اول ځل د غېر‌يهوديانو نه خلق د خپل ځان دپاره خوښ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26328, 'Acts 15:15', 'Acts', 15, 15, '&nbsp;دا د نبيانو د کلام سره هم سمون خورى لکه چې صحيفو کښې ليکلے شوى دى چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26329, 'Acts 15:16', 'Acts', 15, 16, '&nbsp;”د هغې نه پس به زۀ واپس راشم او د داؤد نړېدلے کور به بيا آباد کړم، او زۀ به دا بيا ودان کړم', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26330, 'Acts 15:17', 'Acts', 15, 17, '&nbsp;د دې دپاره چې نور انسانان، يعنې غېر‌يهوديان زما لټون وکړى څوک چې ما رابللى او خپل کړى دى. مالِک خُدائ داسې فرمائى، هغه چې دغه کارونه کوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26331, 'Acts 15:18', 'Acts', 15, 18, '&nbsp;چې د پيړو راسې معلوم دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26332, 'Acts 15:19', 'Acts', 15, 19, '&nbsp;د دې دپاره زما فېصله دا ده چې مونږ هغه غېر‌يهوديانو ته تکليف ورنۀ کړُو څوک چې په خُدائ پاک ايمان راوړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26333, 'Acts 15:20', 'Acts', 15, 20, '&nbsp;بلکې په ليکلو ورته هدايت وکړُو چې بُتانو ته پېش کړے شوې نذرانې او زناکارۍ نه او د مُردار شوى څاروى غوښې نه او د هغې د وينې نه ځان وساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26334, 'Acts 15:21', 'Acts', 15, 21, '&nbsp;ځکه چې د پخوا زمانې نه په هر ښار کښې د موسىٰ د شريعت تعليم ورکول کېدو او په هر سبت به په عبادتخانو کښې تلاوت کېدو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26335, 'Acts 15:22', 'Acts', 15, 22, '&nbsp;بيا رسولانو او مشرانو د ټول جماعت په مشوره دا فېصله وکړه چې په خپل مينځ کښې يو څو کسان خوښ کړى او هغوئ اَنطاکيه ته د پولوس او برنباس سره ولېږى. هغوئ په وروڼو کښې يهوداه چې برسبا ورته وائى، او سيلاس چې په هغوئ کښې ډېر عزتمند وو، غوره کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26336, 'Acts 15:23', 'Acts', 15, 23, '&nbsp;او خط يې ورکړو چې په کښې داسې ليکلے شوى وُو، ”مونږ رسولان او مشران ستاسو وروڼه، تاسو غېر‌يهوديانو ايماندارانو ته چې په اَنطاکيه، شام، او کلکيه کښې يئ سلامونه وايو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26337, 'Acts 15:24', 'Acts', 15, 24, '&nbsp;مونږ اورېدلى دى چې زمونږ ځينى کسان زمونږ د حُکم نه بغېر درغلى دى او په خپلو خبرو يې تاسو پرېشانه کړى يئ او ستاسو ذهنونه يې ګډ‌وډ کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26338, 'Acts 15:25', 'Acts', 15, 25, '&nbsp;مونږ دا فېصله کړې ده چې خپل نمائنده ګان خوښ کړُو او د خپلو خوږو ملګرو برنباس او پولوس سره يې تاسو له درولېږو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26339, 'Acts 15:26', 'Acts', 15, 26, '&nbsp;چا چې خپل ځانونه زمونږ د مالِک عيسىٰ مسيح د نوم دپاره په خطره کښې اچولى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26340, 'Acts 15:27', 'Acts', 15, 27, '&nbsp;د دې دپاره مونږ يهوداه او سيلاس درلېږو او هغوئ به درته په خپله دا خبرې تېرې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26341, 'Acts 15:28', 'Acts', 15, 28, '&nbsp;دا زمونږ او د روحُ القُدس خوښه ده چې د دې ضرورى خبرو نه زيات په تاسو نور بوج وانۀ چوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26342, 'Acts 15:29', 'Acts', 15, 29, '&nbsp;تاسو ته په کار دى چې بُتانو ته د نذر کړې قربانۍ نه، د هغې د وينې او د مُردار شوى څاروى غوښې نه او د زناکارۍ نه ځان ساتئ. کۀ تاسو د دې څيزونو نه ځانونه بچ ساتئ نو تاسو به ښۀ کوئ. وسلام.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26343, 'Acts 15:30', 'Acts', 15, 30, '&nbsp;نو دغه شان دوئ رُخصت کړے شول او اَنطاکيه ته لاړل. هلته هغوئ جماعت يو ځائ جمع کړو او خط يې ورله ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26344, 'Acts 15:31', 'Acts', 15, 31, '&nbsp;کله چې هغوئ دا خط ولوستلو نو هغوئ په دې تسلۍ خوشحاله شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26345, 'Acts 15:32', 'Acts', 15, 32, '&nbsp;يهوداه او سيلاس چې په خپله هم نبيان وُو، هغوئ ايماندارانو ته د ډاډګيرنې او تکړه کېدو دپاره ډېر نصيحت وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26346, 'Acts 15:35', 'Acts', 15, 35, '&nbsp;خو پولوس او برنباس په اَنطاکيه کښې پاتې شول او هلته يې د ډېرو نورو سره د مالِک کلام اورولو او تعليم يې ورکولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26347, 'Acts 15:36', 'Acts', 15, 36, '&nbsp;نو څو ورځې پس پولوس برنباس ته ووئيل چې، ”راځه چې واپس لاړ شُو او ايماندارانو سره مِلاو شُو په هر هغه ښار کښې چرته چې مونږ د مالِک کلام اورولے وو او د هغوئ د حال نه ځان خبر کړُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26348, 'Acts 15:37', 'Acts', 15, 37, '&nbsp;د برنباس دا خواهش وو چې يوحنا چې ورته مرقوس وائى د ځان سره بوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
