(26353, 'Acts 16:1', 'Acts', 16, 1, '&nbsp;پولوس دربې او لستره ته لاړو. هلته تيموتيوس نومې يو مريد وو چې مور يې يهودڼه وه او هغه ايمانداره وه خو د هغۀ پلار يونانى وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
