(26358, 'Acts 16:6', 'Acts', 16, 6, '&nbsp;نو هغوئ د فروګيه او ګلتيه په علاقو واوړېدل ځکه چې روحُ القُدس هغوئ د آسيه په صوبه کښې د کلام اورولو نه منع کړى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26359, 'Acts 16:7', 'Acts', 16, 7, '&nbsp;کله چې هغوئ د موسيه سرحد ته ورسېدل نو هغوئ کوشش وکړو چې بتونيه ته ننوځى خو د عيسىٰ روح هغوئ پرې نۀ ښودل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
