(26361, 'Acts 16:9', 'Acts', 16, 9, '&nbsp;د شپې پولوس رويا وليدله چې يو مِکدونى سړے ولاړ دے او دا مِنت ورته کوى چې، ”مِکدونيه ته راپورې وځه او زمونږ مدد وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26362, 'Acts 16:10', 'Acts', 16, 10, '&nbsp;کله چې هغۀ دا رويا وليده نو مونږ سمدستى کوشش وکړو چې مِکدونيه ته لاړ شُو. زمونږ دا خيال وو لکه چې خُدائ پاک راته وئيلى وى چې هغوئ ته زيرے ورکړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26363, 'Acts 16:11', 'Acts', 16, 11, '&nbsp;نو مونږ د ترواس نه په سمندرى جهاز کښې سوارۀ شُو او نېغ ساموتراکې ته او په بله ورځ نياپوليس ته لاړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26364, 'Acts 16:12', 'Acts', 16, 12, '&nbsp;او د هغه ځائ نه فيليپى ته چې د مِکدونيه په ضِلع کښې لوئ ښار دے او د روميانو کالونى هم ده. مونږ په دې ښار کښې د څو ورځو دپاره پاتې شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26365, 'Acts 16:13', 'Acts', 16, 13, '&nbsp;د سبت په ورځ مونږ د ښار د دروازې نه بهر د سيند غاړې ته لاړو چرته چې زمونږ دا خيال وو چې خلق به د عبادت دپاره راټول شوى وى، مونږ کښېناستو او هلته د راغلو ښځو سره مو خبرې وکړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26366, 'Acts 16:14', 'Acts', 16, 14, '&nbsp;په هغوئ کښې د يوې نوم لِديه وو چې د قيمتى کاسنى رنګ جامو سوداګره وه او د تواتيره د ښار اوسېدونکې وه. هغه د خُدائ پاک عبادت کوونکې وه. مالِک د هغې زړۀ پرانستو او هغې د پولوس کلام قبول کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26367, 'Acts 16:15', 'Acts', 16, 15, '&nbsp;کله چې هغې ته سره د خاندانه بپتسمه ورکړے شوه نو هغې په مونږ زور واچولو او وې وئيل چې، ”کۀ تاسو ما د مالِک ايمانداره ګڼئ نو راشئ او زما په کور کښې مېلمانۀ شئ.“ او هغې مونږ په پاتې کېدو مجبور کړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26368, 'Acts 16:16', 'Acts', 16, 16, '&nbsp;مونږ يوه ورځ چې عبادتخانې ته روان وُو نو يوه نوکره مو وليدله چې پرې د غېب عالم روح ناست وو او هغې خپلو مالِکانو ته د فال کتو په ذريعه ډيرې پېسې ګټلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
