(26393, 'Acts 17:1', 'Acts', 17, 1, '&nbsp;بيا پولوس او سيلاس په امفيپوليس او په اپولونيه تير شول او تِسالونيکيه ته راغلل چرته چې د يهوديانو عبادتخانه وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26394, 'Acts 17:2', 'Acts', 17, 2, '&nbsp;او پولوس د خپل عادت په مطابق د هغوئ عبادتخانې ته تلو او درې هفتې د هر سبت په ورځ د هغوئ سره د صحيفو نه بحث مباحثه کوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26395, 'Acts 17:3', 'Acts', 17, 3, '&nbsp;او دا يې ورته تشريح او ثابت کړل چې مسيح به خامخا تکليفونه زغمى او د مړو نه به بيا ژوندے راپاڅى. او هغۀ ووئيل چې، ”کوم عيسىٰ چې زۀ تاسو ته بيانوم، هم هغه مسيح دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26396, 'Acts 17:4', 'Acts', 17, 4, '&nbsp;په هغوئ کښې ځينې راضى شول او د پولوس او سيلاس سره ملګرى شول او دغه شان د دې ديندارو يونانيانو يو څو عزتمندې ښځې هم راضى شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26397, 'Acts 17:5', 'Acts', 17, 5, '&nbsp;خو يهوديانو د حسد له کبله د څۀ بازارى بدمعاشانو په مدد، جلوس راوويستو او په ښار کښې يې اله ګوله جوړه کړه. هغوئ د ياسون کور راګېر کړو چې پولوس او سيلاس ولټوى او د خلقو ګڼې ته يې راوباسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26398, 'Acts 17:6', 'Acts', 17, 6, '&nbsp;خو چې هغوئ يې ونۀ موندل نو ياسون او ځينې نور ايمانداران يې د ښار منصفانو ته په زور راوستل او دا چغې يې وهلې چې، ”هم دې کسانو ټوله دُنيا په عذاب اخته کړې ده او اوس زمونږ ښار هم په عذابوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26399, 'Acts 17:7', 'Acts', 17, 7, '&nbsp;او ياسون هغوئ د ځان سره دېره کړى دى. هغوئ د قيصر ټول قانون د پښو لاندې کړے دے او دا وائى چې دلته يو بل بادشاه دے چې نوم يې عيسىٰ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26400, 'Acts 17:8', 'Acts', 17, 8, '&nbsp;کله چې خلقو او د ښار منصفانو دا واورېدل نو وارخطا شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');